/// <summary>
/// activate the new button for date and economic batch size
/// </summary>
private void activateItemValidityDateEconomicBatchSizeNew()
{
    if(NDXItemValidityDateEconomicBatchSize::find(InventTable))
    {
        FormCommandButtonControl2.enabled(false);
    }
    else
    {
        FormCommandButtonControl2.enabled(true);
    }
}

public int active()
{
    int ret;

    ret = super();

    element.activateItemValidityDateEconomicBatchSizeNew();

    return ret;
}

public QuotationId createWildcard()
{
    QuotationId quotationid;
    int pos;

    quotationid = NDXMultipleS_SalesQuotationRange_RangeQuotation.text();
    pos = strFind(quotationid, '-', 0, strLen(quotationid));

    if(pos > 0)
    {
        quotationid = strDel(quotationid, pos + 1, strLen(quotationid)-pos) + '*';
    }
    else
    {
        quotationid = quotationid + '*';
    }

    return quotationid;
}
